from dataclasses import dataclass
from typing import List

@dataclass(frozen=True)
class Column:
    name: str
    type: str

class Table:
    def __init__(self, name: str, columns: List[Column], rows: List[List[object]]) -> None:
        if not columns:
            raise SchemaError("empty columns")
        self._name = name
        self._columns = columns
        self._rows = []
        col_names = [c .name for c in columns]
        if len(set(col_names)) != len(col_names):
            raise SchemaError("duplicate column name")
        for row in rows:
            if len(row) != len(columns):
                raise SchemaError("row length mismatch")
            for i, val in enumerate(row):
                if val is None:
                    continue
                if type_of(val) != columns[i].type:
                    if columns[i].type == "FLOAT" and type_of(val) == "INT":
                        val = float(val)
                    else:
                        raise SchemaError("type mismatch in row")
            self._rows.append(row)
        self._rows = rows  # store original for validation

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> List[Column]:
        return self._columns

    @property
    def rows(self) -> List[List[object ]]:
        return self._rows

    def column_index(self, name: str) -> int:
        for i, c in enumerate(self._columns):
            if c.name == name:
                return i
        raise UnknownColumnError("unknown column")
