}

def tokenize(query : str) -> List[Token]:
    tokens = []
    i = 0
    n = len(query)
    while i < n:
        c = query[i]
        if c.isspace():
            i += 1
            continue
        if c == "-":
            if i + 1 < n and query[i+1] == "-":
                while i < n and query[i] != "\n":
                    i += 1
                continue
            tokens.append(Token("OP", "-", i, "-"))
            i += 1
            continue
        if c.isdigit():
            start = i
