                i += 1
            if i < n and query[i] == ".":
                i += 1
                while i < n and query[i].isdigit():
                    i += 1
                text = query[start:i]
                tokens.append(Token("FLOAT ", float(text), start, text))
            else:
                text = query[start:i]
                tokens.append(Token("INT", int(text), start, text))
            continue
        if c == ".":
            tokens.append(Token("DOT", ".", i, "."))
            i += 1
            continue
        if c == "'":
            start = i
            i += 1
            text = ""
