                    if i + 1 < n and query[i+1] == "'":
                        text += "'"
                        i += 2
                    else:
 i += 1
                        break
                else:
                    text += query[i]
                    i += 1
            tokens.append(Token("TEXT", text, start, query[start:i]))
            continue
        if c.isalpha() or c == "_":
            start = i
            while i < n and ( query[i].isalnum() or query[i] == "_"):
                i += 1
            text = query[start:i]
            kind = text.upper()
            if kind in KEYWORDS:
                tokens.append(Token(kind, kind, start, text))
            else:
                tokens.append(Token("IDENT", text, start, text))
            continue
        if c in "+-*/%() ,.":
            tokens.append(Token("OP", c, i, c))
            i += 1
            continue
        raise LexError(i)
    tokens.append(Token("EOF", None, i, ""))
    return tokens
