from __future__ import annotations

from dataclasses import dataclass

from microdb.errors import (
    AmbiguousColumnError,
    ArityError,
    AggregateError,
    TypeMismatchError,
    UnknownColumnError,
    UnknownFunctionError,
    UnknownTableError,
