from microdb.parser import Binary, Call, ColumnRef, IsNull, Literal, Unary
from microdb.value import (
    and_,
    arith,
    as_logical,
    compare_eq,
    compare_ge,
    compare_gt,
    compare_le,
    compare_lt,
    compare_ne,
    is_numeric,
    negate,
    not_,
    or_,
    type_of,
)

AGGS = frozenset({"count", "sum", "avg", "min", "max"})
_CMP = {
    "=": compare_eq,
    "<>": compare_ne,
    "<": compare_lt,
    "<=": compare_le,
    ">": compare_gt,
    ">=": compare_ge,
}
_ARITY: dict[str, tuple[int, int | None]] = {
    "upper": (1, 1),
    "lower": (1, 1),
    "length": (1, 1),
    "abs": (1, 1),
    "concat": (2, None),
    "coalesce": (1, None),
    "count": (1, 1),
    "sum": (1, 1),
    "avg": (1, 1),
    "min": (1, 1),
    "max": (1, 1),
}


@dataclass
class EvalCtx:
    col_tables: list[str]
    col_names: list[str]
    row: list[object]
    aliases: dict[str, object] | None = None
    aggs: dict[int, object] | None = None
    allow_input: bool = True


