from __future__ import annotations

import dataclasses
import functools

from microdb.aggregate import eval_aggregate
from microdb.errors import GroupingError, UnknownTableError
from microdb.expr import (
    EvalCtx,
    bind_expr,
    collect_aggregates,
    eval_expr,
    eval_predicate,
    expr_equal,
    has_aggregate,
    item_source,
    walk_children,
