import inspect
import microdb
import microdb.executor as ex
import microdb.planner as pl
import microdb.schema as sc
import microdb.value as va
import microdb.lexer as lx
import microdb.parser as pa
import microdb.errors as er
import microdb.aggregate as ag
import microdb.expr as exp
from microdb.__main__ import main

missing = []
for mod in [microdb, ex, pl, sc, va, lx, pa, er, ag, exp]:
    for name, obj in vars(mod).items():
        if name.startswith('_'):
            continue
        if inspect.isfunction(obj) and obj.__module__ == mod.__name__:
            sig = inspect.signature(obj)
            if sig.return_annotation is inspect.Signature.empty:
                missing.append((mod.__name__, name, 'return'))
            for p in sig.parameters.values():
                if p.name in ('self', 'cls'):
                    continue
                if p.annotation is inspect.Parameter.empty:
                    missing.append((mod.__name__, name, p.name))
        if inspect.isclass(obj) and obj.__module__ == mod.__name__:
            for n, m in vars(obj).items():
                if n.startswith('_') and n not in ('__init__', '__iter__', '__len__', '__getitem__'):
                    continue
                fn = m if inspect.isfunction(m) else getattr(m, 'fget', None) if isinstance(m, property) else None
                if inspect.isfunction(fn):
                    sig = inspect.signature(fn)
                    if sig.return_annotation is inspect.Signature.empty:
                        missing.append((mod.__name__, obj.__name__+'.'+n, 'return'))
                    for p in sig.parameters.values():
                        if p.name in ('self', 'cls'):
                            continue
                        if p.annotation is inspect.Parameter.empty:
                            missing.append((mod.__name__, obj.__name__+'.'+n, p.name))
sig = inspect.signature(main)
print('main', sig)
print('missing', missing)
